import { timeout } from 'rxjs';

@Component({
    selector: 'app-transaction-start',
    host: { class: 'childRouteFlex' },
    templateUrl: './transaction-start.component.html',
    styleUrls: ['./transaction-start.component.css']
})
export class TransactionStartComponent {
    showButtonChoseIsIncome = false;
    firstLoad = true;

    buttonCreate: any;

    constructor() {
        // this.buttonCreate = document.getElementById('buttonCreate');
		// this.buttonCreate.addEventListener('mouseover', (event) => {
		// 	// Get the position of the mouse relative to the button
		// 	const x = event.clientX - button.getBoundingClientRect().left;
		// 	const y = event.clientY - button.getBoundingClientRect().top;

		// 	// Calculate the percentage of mouse position
		// 	const xPercent = (x / button.clientWidth) * 100;
